#include "inverse_trig_cases.h"
static agc_word next(uint32_t *s){*s=*s*UINT32_C(1664525)+UINT32_C(1013904223);return (agc_word)((*s>>8)&077777u);}
void inverse_trig_input(apollo_overlay_state *m,agc_word *irq,enum inverse_trig_mission mission,uint32_t n){static const agc_word edge[16]={0,077777,1,077776,017777,020000,020001,020002,057777,057776,057775,060000,037777,040000,2,077775};uint32_t seed=UINT32_C(0xabc31a2)+(n>>14)*UINT32_C(0x71721);unsigned i;for(i=0;i<2048u;++i)m->words[i]=next(&seed);m->words[0]=(agc_word)(n*37u);m->words[1]=(agc_word)(n*71u);m->words[2]=next(&seed);m->words[3]=(agc_word)(((n>>4)&7u)<<8);m->words[4]=0;m->words[5]=(agc_word)(mission==INVERSE_TRIG_LM?((n&1u)?03610u:03612u):((n&1u)?03607u:03611u));m->words[6]=(agc_word)(m->words[3]>>8);m->words[7]=0;m->words[023]=(agc_word)((n>>3)&1u);m->words[0163]=(agc_word)(n>>1);m->words[0154]=(agc_word)(n>>1);m->words[0155]=next(&seed);m->words[0156]=0;if(n<4096u){m->words[0154]=edge[(n>>1)&15u];m->words[0155]=edge[(n>>5)&15u];m->words[0156]=edge[(n>>9)&7u];}*irq=(agc_word)((n>>7)&1u);}
